const $=q=>document.querySelector(q), $$=q=>[...document.querySelectorAll(q)];
const KEY='softstarter-lab-v1';let storageOK=true,db={version:1,runs:{},projection:false},route='home',active=null,index=0,selected=null,lastResult=null,animation=null;
// Estado apenas em memória; remove o progresso de versões anteriores.
try{localStorage.removeItem(KEY);}catch{}
function save(){}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function run(s=active){let r=db.runs[s.id];if(!r||!r.answers||!r.params){r=db.runs[s.id]={index:0,answers:{},params:{initial:30,ramp:1,current:30,decel:0},tests:[],done:false};}return r;}
function fmt(n,d=0){return Number(n).toLocaleString('pt-BR',{maximumFractionDigits:d,minimumFractionDigits:d});}
function motorArt(kind='pump',hero=false){const unique=kind+(hero?'hero':'card');return `<svg class="technical-art" viewBox="0 0 480 270" role="img" aria-label="Ilustração técnica de ${kind==='pump'?'motor e bomba centrífuga':kind==='fan'?'ventilador industrial':'esteira transportadora'}"><defs><linearGradient id="body${unique}" x2=".8" y2="1"><stop stop-color="#8dada2"/><stop offset="1" stop-color="#325c55"/></linearGradient><linearGradient id="metal${unique}" x2=".7" y2="1"><stop stop-color="#e0e7d9"/><stop offset="1" stop-color="#96aea2"/></linearGradient></defs><ellipse cx="249" cy="229" rx="155" ry="12" fill="#14382c" opacity=".09"/>${kind==='conveyor'?`<path d="M73 160L330 112L414 152L155 204Z" fill="#758c7e" stroke="#365c50"/><path d="M73 160V177L155 221L414 168V152L155 204Z" fill="#4c6c5e"/><path d="M109 184V224M379 182V223M176 218V244" stroke="#3c5f51" stroke-width="8"/>${[0,1,2].map((v)=>`<g transform="translate(${145+v*73} ${131-v*13})"><path d="M0 0L37-7L62 6L25 14Z" fill="#ceb78b"/><path d="M0 0V34L25 48V14Z" fill="#ad9269"/><path d="M25 14L62 6V39L25 48Z" fill="#e3cda4"/></g>`).join('')}<path d="M90 172L146 200M123 165L180 192M325 127L384 154" stroke="#c3d1bf" stroke-width="2"/>`:kind==='fan'?`<path d="M161 204L150 232H300L288 204" fill="#4d6d61"/><path d="M186 58L281 77L320 137L304 201L245 224L165 205L135 142L148 91Z" fill="url(#body${unique})" stroke="#3a6056" stroke-width="2"/><ellipse cx="226" cy="141" rx="69" ry="75" fill="#243f3b"/><g transform="translate(226 141)" class="rotor"><path d="M0 0C-56-74 9-83 6-23Z M0 0C80-43 73 25 21 6Z M0 0C-1 93-57 54-16 15Z" fill="#94b09f"/><circle r="16" fill="#c3d3bf"/></g><ellipse cx="226" cy="141" rx="69" ry="75" fill="none" stroke="#b2c3b0" stroke-width="4"/><path d="M225 65V217M159 139H293M177 87L273 198M176 197L272 85" stroke="#d0ddc8" opacity=".3"/>`:`<path d="M91 208L284 174L372 211L180 244Z" fill="#8ea89a" stroke="#557867"/><path d="M91 208V217L180 252V244M180 252L372 219V211" fill="#577766"/><path d="M141 189V219L172 231V201M251 174V198L282 210V180" fill="#355b50"/><path d="M126 104L228 83Q266 79 278 122L283 174L181 198Z" fill="url(#body${unique})" stroke="#365c51" stroke-width="2"/><ellipse cx="151" cy="150" rx="43" ry="51" transform="rotate(-20 151 150)" fill="#436d5d" stroke="#abc3aa" stroke-width="3"/><ellipse cx="151" cy="150" rx="27" ry="34" transform="rotate(-20 151 150)" fill="#24493e"/>${Array.from({length:7},(_,i)=>`<path d="M${168+i*13} ${98-i*2}L${185+i*13} ${184-i*2}" stroke="#b3c9ae" stroke-width="3" opacity=".65"/>`).join('')}<path d="M191 94V71L225 64L246 76V92L214 101Z" fill="#5e8371" stroke="#31564b"/><path d="M281 141L317 145L324 160L283 164" fill="#bbc8b5"/><path d="M320 174C289 151 309 117 337 116C371 115 384 144 370 171L366 201L329 211Z" fill="url(#metal${unique})" stroke="#5d7d69" stroke-width="2"/><path d="M342 117V80L370 72V136" fill="#b1c4a9" stroke="#5d7d69" stroke-width="2"/><ellipse cx="355" cy="77" rx="15" ry="7" fill="#466c5b"/><path d="M370 161L402 150V178L368 190" fill="#a3bba0" stroke="#5d7d69"/><ellipse cx="402" cy="164" rx="8" ry="15" fill="#446b57"/>`}${hero?`<path d="M60 67L107 82M367 52L342 82M411 221L374 212" fill="none" stroke="#889d83" stroke-dasharray="3 3"/><circle cx="60" cy="67" r="3" fill="#648356"/><text x="18" y="54" fill="#64806a" font-size="9" font-family="monospace">MOTOR 3~</text><text x="342" y="41" fill="#64806a" font-size="9" font-family="monospace">CARGA MECÂNICA</text>`:''}</svg>`;}
function shell(inner){document.body.classList.toggle('projection',!!db.projection);$('#app').innerHTML=`<aside class="rail"><a href="#" class="brand" data-action="home"><span class="brandmark">ϟ</span><span>Soft-Starter<span style="color:#bdd795"> Lab</span><small>SIMULADOR INDUSTRIAL</small></span></a><div class="rail-label">Ambiente de aprendizagem</div><nav><button class="navbtn ${route==='home'||route==='mission'?'active':''}" data-action="home"><span class="navicon">▦</span><span>Missões industriais</span></button><button class="navbtn" data-action="reference"><span class="navicon">▤</span><span>Biblioteca técnica</span></button><button class="navbtn ${route==='reports'?'active':''}" data-action="reports"><span class="navicon">▥</span><span>Resultados</span></button><button class="navbtn" data-action="guide"><span class="navicon">◉</span><span>Guia do laboratório</span></button></nav><div class="rail-bottom"><div class="online"><span class="dot"></span> Laboratório virtual disponível</div>Acionamentos eletrônicos<br>Prof. Douglas Ferreira da Silva<div style="margin-top:14px;font-size:9px;color:#7e9a90">SSW-05 PLUS · EDIÇÃO DIDÁTICA</div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">Laboratório <span style="margin:0 10px;color:#a5afa5">/</span> <strong>${route==='home'?'Visão geral':route==='mission'?active.name:'Resultado da situação'}</strong></div><div class="top-actions"><button class="mini-link" data-action="projection" aria-pressed="${!!db.projection}">${db.projection?'Sair da projeção':'Modo projeção'}</button><span class="pill"><span class="dot" style="background:#6c9365"></span> Aprenda experimentando</span><span class="avatar">DF</span></div></header>${!storageOK?'<div class="storage-warn">O navegador bloqueou o salvamento local. O progresso será mantido somente nesta sessão.</div>':''}<main class="content" id="main">${inner}<footer class="footer-note"><span>Simulação educacional • Os gráficos não representam medições reais.</span><span>SSW-05 Plus · Manual 2.3X</span></footer></main></div>`;bindGlobal();}
function home(){stopAnimation();route='home';const completed=SCENARIOS.filter(s=>run(s).done).length;const errors=Object.values(db.runs).reduce((n,r)=>n+Object.values(r.answers||{}).reduce((a,b)=>a+(b.errors||0),0),0);shell(`<div class="pagehead"><div><h2>Seu próximo desafio começa aqui.</h2><div class="sub">Assuma o painel. Analise, ajuste e coloque em operação.</div></div><button class="btn light" data-action="guide">Como funciona <span>↗</span></button></div><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot" style="background:#6d8a55"></span> DA ANÁLISE AO COMISSIONAMENTO</div><h1>Decisões reais.<br>Aprendizado na prática.</h1><p>Explore três situações industriais, interprete as evidências e descubra como cada ajuste muda o comportamento do motor.</p><button class="btn" data-start="${SCENARIOS.find(s=>!run(s).done)?.id||'pump'}">${completed?'Continuar explorando':'Iniciar primeira missão'} <span>→</span></button></div><div class="hero-art">${motorArt('pump',true)}<span class="art-label">FIG. 01 / CONJUNTO MOTOR–BOMBA</span></div></section><div class="stats"><div class="stat"><div class="stat-icon">▦</div><div><strong>3 missões</strong><span>Aplicações e percursos distintos</span></div></div><div class="stat"><div class="stat-icon">✓</div><div><strong>${completed} de 3</strong><span>Missões concluídas</span></div></div><div class="stat"><div class="stat-icon">↻</div><div><strong>Experimente</strong><span>Corrija, compare e aprenda</span></div></div></div><div class="sectionhead"><div><h3>Escolha sua missão</h3><p>Cada máquina apresenta um novo desafio técnico.</p></div><span>01 — 03 / PERCURSO PRÁTICO</span></div><section class="cards">${SCENARIOS.map(s=>{const r=run(s),count=Object.values(r.answers).filter(a=>a.passed).length;return `<article class="scenario"><div class="card-art ${s.kind}"><span class="card-number">MISSÃO ${s.num}</span><span class="level">${s.level}</span>${motorArt(s.kind)}</div><div class="card-body"><div class="eyebrow">${s.tag}</div><h3>${s.name}</h3><p>${s.short}</p><div class="card-meta"><span>◷ ${s.duration}</span><span>${r.done?'✓ Concluída':count?`${count}/${s.steps.length} etapas`:'○ Não iniciada'}</span></div><button class="btn ${s.id!=='pump'?'light':''}" data-start="${s.id}">${r.done?'Ver relatório':count?'Continuar missão':'Iniciar simulação'} <span>→</span></button></div></article>`}).join('')}</section><div class="notice" style="margin-top:23px">Um ambiente para testar decisões, não apenas memorizar respostas. Consulte as referências sempre que precisar.</div>`);}
function start(id){stopAnimation();active=SCENARIOS.find(s=>s.id===id);const r=run();if(r.done)return report(active);index=Math.min(r.index||0,active.steps.length-1);while(index>0&&!run().answers[active.steps[index-1].id]?.passed)index--;route='mission';renderStep();}
function plate(s){return `<div class="plate"><header><span>MOTOR DE INDUÇÃO 3~</span><span>LAB / ${s.num}</span></header><table><tr><td>Potência</td><td>${fmt(s.kw,1)} kW · ${s.cv} cv</td></tr><tr><td>Tensão Δ / Y</td><td>220 / 380 V</td></tr><tr><td>Corrente Δ / Y</td><td>${s.voltage===220?`${fmt(s.amps,1)} / ${fmt(s.otherAmps,1)}`:`${fmt(s.otherAmps,1)} / ${fmt(s.amps,1)}`} A</td></tr><tr><td>Frequência / rotação</td><td>60 Hz / ${s.rpm} rpm</td></tr><tr><td>cos φ / rendimento</td><td>${fmt(s.pf,2)} / ${fmt(s.eff,1)}%</td></tr>${s.kind==='conveyor'?'<tr><td>Ligação nesta rede</td><td>Estrela (Y) · 380 V entre fases</td></tr>':''}<tr><td>Serviço / terminais</td><td>S1 / 6</td></tr></table><small>PLACA DIDÁTICA · valores hipotéticos para a atividade</small></div>`;}
function facts(s){return `<div class="facts">${[['MOTOR',s.cv+' cv'],['REDE',s.kind==='conveyor'?'380 V entre fases':s.net+' V'],['CORRENTE',s.amps+' A'],['OPERAÇÃO','Velocidade fixa']].map(([a,b])=>`<div class="fact"><small>${a}</small><strong>${b}</strong></div>`).join('')}</div>`;}
function renderStep(){stopAnimation();selected=null;lastResult=null;route='mission';const s=active,step=s.steps[index],r=run(),a=r.answers[step.id];let body='';
if(step.show==='ged')body+=`<figure class="ged-inline"><figcaption><strong>Tabela GED-13</strong><span>Compare a potência do motor e a tensão entre fases antes de decidir.</span></figcaption><img src="ged13.png" alt="Tabela GED-13: dispositivos para redução da corrente de partida de motores trifásicos"><p>Para esta atividade, a partida direta está na faixa até 5 cv em 220 V e até 7,5 cv em 380 V. Avalie também a necessidade do processo.</p></figure>`;
if(step.show==='plate')body+=plate(s);
if(step.show==='models')body+=`<div class="flowstrip"><span>Rede: ${s.voltage} V</span><span>Motor: ${s.amps} A</span><span>Controle: 220 Vca</span><span>Temperatura: 30 °C</span></div>`;
if(step.show==='protection')body+=`<div class="flowstrip"><span>Seccionamento</span><span>Proteção de potência</span><span>K1</span><span>SSW-05</span><span>Motor + PE</span></div><button class="mini-link" data-action="components">Ver combinações de proteção ↗</button>`;
if(step.show==='fault'){const f=FAULTS[step.faultIndex];body+=`<div class="fault-display"><div class="fault-code">${f.code||'••••'}</div><div><div class="ledrow"><span class="led red blink"></span> ${f.led}</div><p>${f.flashes?`${f.flashes} piscadas por grupo`:'Falha sinalizada'}</p></div></div>`;}
if(step.type==='choice'){body+=`<div class="question">${step.prompt}</div><div class="choices">${step.options.map((v,i)=>`<button class="choice" data-option="${i}" aria-pressed="false"><span class="letter">${String.fromCharCode(65+i)}</span><span>${v}</span></button>`).join('')}</div>`;}
if(step.type==='terminals'){body+=`<div class="question">${step.prompt}</div><div class="terminal-grid">${[['R/1L1 · S/3L2 · T/5L3','Potência'],['U/2T1 · V/4T2 · W/6T3','Saída'],['A1 · A2','Alimentação'],['DI1 · DI2','Entradas digitais']].map(([t,l],i)=>`<button class="terminal" data-option="${i}" aria-pressed="false">${t}<small>${l}</small></button>`).join('')}</div><button class="mini-link" data-action="terminals">Ver funções e tensões dos bornes ↗</button>`;}
if(step.type==='current'){body+=`<div class="current-layout">${frontPanel(s,false,true)}<div class="current-reference">${plate(s)}${adjustmentGuide(s,'current')}</div></div>`;}
if(step.type==='simulation'||step.type==='stop'){body+=adjustmentGuide(s,step.type)+`<div class="question">${step.prompt}</div>`+simulationPanel(s,step.type==='stop');if(step.type==='stop')body+=`<div class="choices" style="margin-top:20px">${[
{value:1,text:'Abrir o contator de potência ao retirar DI1, mantendo A1/A2 alimentados.'},
{value:0,text:'Retirar o comando de DI1 e manter potência e controle alimentados até o fim da rampa.'},
{value:2,text:'Manter DI1 acionada e reduzir apenas DECEL TIME para iniciar a parada.'},
{value:3,text:'Retirar a alimentação de A1/A2, mantendo a rede de potência durante a rampa.'}
].map((option,i)=>`<button class="choice" data-option="${option.value}" aria-pressed="false"><span class="letter">${String.fromCharCode(65+i)}</span>${option.text}</button>`).join('')}</div>`;}
if(step.type==='checklist'){const list=s.kind==='conveyor'?['Analisei a necessidade de suavizar a partida em velocidade fixa.','Conferi corrente de placa, seleção, proteção e conexões.','Verifiquei atrito, correia e carga antes dos ajustes.','Ajustei pedestal e rampa para iniciar sem tranco e acelerar a carga.','Investiguei Stall antes de considerar o reset.','Mantive DECEL TIME em OFF para a parada normal.']:['Analisei aplicação, rede e corrente de placa.','Conferi seleção, proteções e conexões.','Calculei MOTOR CURRENT com a corrente nominal.','Ajustei e analisei a partida virtual.','Investiguei a falha antes de considerar o reset.',s.kind==='pump'?'Avaliei a parada e a necessidade de manter alimentação durante a rampa.':'Reconheci os limites térmicos e de frequência de partidas.'];body+=`<div class="checklist">${list.map((t,i)=>`<label><input type="checkbox" id="check${i}" ${a?.passed?'checked':''}>${t}</label>`).join('')}</div><div class="notice">Esta conclusão vale para a atividade virtual. A instalação real exige projeto, qualificação, procedimentos de segurança e validação em campo.</div>`;}
shell(`<div class="mission-top"><button class="mini-link no-print" data-action="home">← Todas as missões</button><h1>${s.name}</h1><div class="sub">MISSÃO ${s.num} · ${s.level} · ${s.duration}</div></div><div class="mission-layout"><aside class="steps"><span>SEU PERCURSO</span>${s.steps.map((st,i)=>`<button class="stepbtn ${i===index?'current':''} ${r.answers[st.id]?.passed?'done':''}" data-step="${i}" ${i>0&&!r.answers[s.steps[i-1].id]?.passed?'disabled':''}><b>${r.answers[st.id]?.passed?'✓':String(i+1).padStart(2,'0')}</b>${st.title}</button>`).join('')}</aside><div class="workspace"><div class="panel"><div class="eyebrow">ETAPA ${String(index+1).padStart(2,'0')} / ${s.steps.length} <span style="margin-left:auto">${Math.round(index/s.steps.length*100)}%</span></div><div class="progress"><div style="width:${index/s.steps.length*100}%"></div></div><h2>${step.title}</h2>${index===0?`<div class="os"><strong>OS ${s.num} / Solicitação de manutenção</strong><p>${s.brief}</p></div>${facts(s)}`:''}<p class="context">${step.context}</p>${body}<div id="feedback" class="feedback" role="status" aria-live="polite"></div><div class="step-actions"><button class="btn light" id="submit">${step.type==='checklist'?'Confirmar verificações':step.type==='simulation'?'Validar comissionamento':'Confirmar decisão'}</button><button class="btn" id="next" ${a?.passed?'':'disabled'}>${index===s.steps.length-1?'Concluir e ver resultado':'Continuar'} <span>→</span></button></div></div><div class="toolrow"><button class="mini-link" data-action="reference">▤ Biblioteca técnica</button><button class="mini-link" data-action="restart">↻ Reiniciar esta missão</button></div></div></div>`);
$$('[data-option]').forEach(el=>el.onclick=()=>{selected=Number(el.dataset.option);$$('[data-option]').forEach(e=>{e.classList.toggle('selected',e===el);e.setAttribute('aria-pressed',String(e===el));});});
$$('[data-step]').forEach(el=>el.onclick=()=>{index=Number(el.dataset.step);renderStep();});$('#submit').onclick=submit;$('#next').onclick=next;
if(step.type==='simulation'||step.type==='stop')bindSimulation(step.type==='stop');
if(step.type==='current')$('#current').oninput=e=>{const v=Number(e.target.value);r.params.current=v;$('#current-value').textContent=v+' %';$('#current-knob').style.setProperty('--angle',((v-30)/70*270-135)+'deg');};
if(a?.passed){feedback(true,'Etapa já concluída','Você pode consultar novamente. Sua primeira tentativa original permanece registrada.');$('#submit').disabled=true;$$('[data-param],#simulate,#current,[data-option],.checklist input').forEach(e=>e.disabled=true);}
}
function feedback(good,title,msg){const f=$('#feedback');f.className=`feedback visible ${good?'good':'bad'}`;f.innerHTML=`<strong>${esc(title)}</strong>${esc(msg)}`;}
function record(ok){const r=run(),id=active.steps[index].id;let a=r.answers[id];if(a?.passed)return;a=r.answers[id]||{attempts:0,errors:0,passed:false};a.attempts++;if(!ok)a.errors++;a.passed=ok;r.answers[id]=a;save();}
function submit(){const s=active,step=s.steps[index],r=run();let ok=false,msg='';
if(step.type==='choice'){if(selected===null)return feedback(false,'Selecione uma decisão','Escolha uma opção antes de confirmar.');ok=selected===step.correct;msg=step.why[selected];}
if(step.type==='terminals'){if(selected===null)return feedback(false,'Selecione um grupo de bornes','Clique no painel antes de confirmar.');ok=selected===2;msg=ok?'A1 e A2 alimentam a eletrônica: 90–250 Vca. A fonte de 220 Vca é compatível. Não aplique 380 V diretamente nesses bornes.':'R/S/T recebem potência; U/V/W alimentam o motor; DI1/DI2 são entradas digitais; 13, 14/23 e 24 são contatos de saída. Procure a alimentação da eletrônica.';}
if(step.type==='current'){const raw=$('#current').value,v=Number(raw);r.params.current=v;ok=raw!==''&&Number.isFinite(v)&&v>=30&&v<=100&&Math.abs(v-s.amps/s.ssw*100)<=2;msg=ok?`${s.amps} ÷ ${s.ssw} × 100 = ${fmt(s.amps/s.ssw*100,1)}%. O ajuste está dentro da tolerância didática.`:v<30||v>100?'O ajuste precisa estar entre 30% e 100%. Se a relação real estiver fora dessa faixa, é necessário rever a seleção.':'Divida a corrente nominal do motor pela corrente nominal da SSW e multiplique por 100. Confira a placa e refaça o cálculo.';}
if(step.type==='simulation'){if(!lastResult)return feedback(false,'Execute o ensaio','Ajuste o painel e clique em Simular partida antes de validar.');ok=lastResult.good;msg=resultText(lastResult);}
if(step.type==='stop'){if(!lastResult||selected===null)return feedback(false,'Complete a avaliação','Simule a parada e selecione como comandá-la.');ok=r.params.decel>0&&selected===0;msg=selected===1?'Abrir a alimentação de potência interrompe a rampa. O comando deve permitir que a soft-starter permaneça alimentada durante a parada normal.':selected===2?'DECEL TIME define a duração da parada; alterar o trimpot não substitui retirar o comando de funcionamento de DI1.':selected===3?'A eletrônica precisa permanecer alimentada para executar a rampa. Retirar A1/A2 impede essa execução.':r.params.decel===0?'Habilite a desaceleração e compare a curva com a parada livre.':'Retire o comando e mantenha a alimentação durante a rampa de parada normal. A aplicação em bombas busca amenizar transientes, sem garantia universal.';}
if(step.type==='checklist'){ok=$$('.checklist input').every(e=>e.checked);msg=ok?s.conclusion:'Confirme todas as verificações antes de encerrar o comissionamento.';if(!ok)return feedback(false,'Revisão incompleta',msg);}
record(ok);feedback(ok,ok?'Decisão validada':'Reveja sua decisão',msg);$('#next').disabled=!r.answers[step.id]?.passed;if(ok){$('#submit').disabled=true;$$('[data-param],#simulate,#current,[data-option],.checklist input').forEach(e=>e.disabled=true);}}
function next(){if(!run().answers[active.steps[index].id]?.passed)return;if(index===active.steps.length-1){run().done=true;run().finished=new Date().toISOString();save();return report(active);}index++;run().index=index;save();renderStep();}
function adjustmentGuide(s,type){
 if(type==='current')return `<section class="adjustment-guide"><div class="guide-title">Como ajustar MOTOR CURRENT</div><p>Leia a corrente de placa correspondente à tensão da rede e confira a corrente nominal indicada na soft-starter.</p><p class="guide-goal"><b>Ajuste (%) = corrente nominal do motor ÷ corrente nominal da soft-starter × 100</b></p><p>Use a corrente nominal de placa. O ajuste deve ficar entre 30% e 100%; se a relação estiver fora dessa faixa, reveja a seleção.</p></section>`;
 if(type==='stop')return `<section class="adjustment-guide"><div class="guide-title">O que buscar na parada da bomba</div><h3>Reduzir a tensão de forma gradual</h3><p>Compare DECEL TIME em OFF com uma rampa habilitada. Observe a retirada gradual de tensão e a resposta da rotação, buscando uma parada menos brusca.</p><p>Na instalação, o objetivo é amenizar os impactos hidráulicos. O resultado depende da tubulação e da carga; a rampa não garante frenagem nem elimina todo golpe de aríete.</p><p class="guide-goal"><strong>Durante o ensaio:</strong> retire o comando de funcionamento e mantenha a alimentação necessária até o fim da rampa. O gráfico mostra a resposta do motor; a pressão hidráulica não é calculada.</p></section>`;
 const focus=s.kind==='pump'?'Busque movimento inicial sem demora e sem impacto no conjunto motor–bomba.':s.kind==='fan'?'A carga tem maior inércia: dê tempo para acelerar, acompanhando a corrente antes da entrada do by-pass.':'Vença o atrito inicial sem deixar a esteira parada nem dar um tranco que desloque as caixas.';
 return `<section class="adjustment-guide compact-guide"><p>${focus}</p><div class="adjustment-columns"><div><h3>Pedestal</h3><p>Tensão suficiente para iniciar prontamente, sem tranco. Baixa: falta torque. Alta: pode elevar corrente e impacto.</p></div><div><h3>Aceleração</h3><p>Busque rotação próxima do regime até o fim da rampa. Curto: pode elevar a corrente. Longo: pode prolongar corrente elevada e aquecimento.</p></div></div><p class="guide-goal"><b>Busque:</b> movimento sem demora, aceleração suave e motor próximo do regime ao fim da rampa. Analise o pico junto da duração da corrente e da capacidade do conjunto.</p><p class="guide-tip">Compare três tempos de rampa. Altere um ajuste por vez e observe corrente, rotação e indicação de falha. Uma rampa maior não garante pico menor. Não há tempo ideal fixo nem limite universal de pico.</p>${startingReferences()}</section>`;
}
function startingReferences(){
 return `<section class="starting-references"><h3>Referências para o ensaio</h3><p><b>In significa corrente nominal.</b> Identifique se a referência corresponde ao <b>motor</b> ou à <b>soft-starter</b>, pois essas correntes podem ser diferentes.</p><table class="data"><thead><tr><th>Pico de corrente no motor</th><th>Referência didática</th></tr></thead><tbody><tr><td>Até 2 × In do motor</td><td>Corrente relativamente baixa. Confirme que existe torque suficiente para acelerar a carga.</td></tr><tr><td>Entre 2 e 3 × In do motor</td><td>Faixa inicial favorável, quando compatível com a carga e a duração da partida.</td></tr><tr><td>Entre 3 e 4 × In do motor</td><td>Pode ser aceitável, dependendo da duração, do dimensionamento e da corrente na transição.</td></tr><tr><td>Acima de 4 × In do motor</td><td>Exige maior atenção à capacidade elétrica e térmica do conjunto.</td></tr></tbody></table><p class="small">Essas faixas ajudam a interpretar o ensaio; não representam limites universais de proteção.</p><div class="guide-goal"><b>Capacidade de partida:</b> quando a corrente nominal da soft-starter é igual à do motor, considere a referência de <b>3 × In da soft-starter durante 10 s</b>, nas condições especificadas para o equipamento.<br><b>Observe:</b> analise quanto tempo a corrente permanece elevada. Um pico breve de 3 × In e uma corrente mantida nesse patamar durante vários segundos têm efeitos diferentes. Uma rampa superior a 10 s, isoladamente, não determina uma condição inadequada.</div><p><b>Na transição para o by-pass:</b> observe a corrente em relação à referência ajustada do motor. A proteção Stall considera <b>2 × essa referência</b>. A proteção de sobrecorrente antes do by-pass possui um limiar próprio da versão da soft-starter.</p><p><b>Avalie o conjunto:</b> início do movimento, suavidade, velocidade ao término da rampa, corrente e duração da partida. A atuação térmica real depende das curvas do equipamento, do histórico e da frequência de partidas.</p></section>`;
}
function frontPanel(s,stop,currentMode=false){
 const p=run().params;
 const dial=(key,label,min,max,value,unit,enabled)=>{const angle=(value-min)/(max-min)*270-135;return `<div class="hardware-dial ${enabled?'adjustable':'fixed'}"><label ${enabled?`for="${key}"`:''}>${label}</label><div class="dial-face"><div class="dial-ticks" aria-hidden="true">${Array.from({length:11},(_,i)=>`<i style="--tick:${-135+i*27}deg"></i>`).join('')}</div><div class="knob" ${enabled?`id="${key}-knob"`:''} style="--angle:${angle}deg"></div>${enabled?`<input type="range" id="${key}" min="${min}" max="${max}" step="1" value="${value}" data-param="${key}" data-unit="${unit}" aria-label="${label.replace('<br>',' ')}">`:''}<span class="dial-min">${min===0?'OFF':min+unit}</span><span class="dial-max">${max+unit}</span></div><output ${enabled?`id="${key}-value"`:''}>${key==='decel'&&value===0?'OFF':value+' '+unit}</output>${!enabled?(currentMode?'<small>inativo nesta etapa</small>':'<small>ajuste já definido</small>'):'<small>arraste ou use ← →</small>'}</div>`;};
 const terminals=(labels,small=false)=>`<div class="${small?'control-terminals':'power-terminals'}" aria-hidden="true">${labels.map(l=>`<span><b>${l}</b><i></i></span>`).join('')}</div>`;
 return `<div class="hardware-stage"><div class="device physical-device" aria-label="Painel didático inspirado na disposição da SSW-05, sem marca"><div class="housing-cap top-cap">${terminals(['R / 1L1','S / 3L2','T / 5L3'])}</div><div class="hardware-front"><div class="left-face"><div class="device-name">SOFT<br><b>STARTER</b><span>PARTIDA SUAVE · ${s.ssw} A</span></div><div class="dip-bank" aria-label="Representação das proteções habilitadas"><span>PROTECTION</span><div class="dip-switches" aria-hidden="true">${Array.from({length:5},()=>'<i></i>').join('')}</div><small>ON</small></div><div class="hardware-reset" aria-hidden="true"><i></i> RESET</div><div class="dial-grid">${dial('ramp','ACCEL<br>TIME',1,20,p.ramp,'s',!stop&&!currentMode)}${dial('current','MOTOR<br>CURRENT',30,100,p.current,'%',currentMode)}${dial('initial','PEDESTAL<br>VOLTAGE',30,80,p.initial,'%',!stop&&!currentMode)}${dial('decel','DECEL<br>TIME',0,20,p.decel,'s',stop&&!currentMode)}</div></div><div class="right-face">${terminals(['A1','A2','DI1','DI2'],true)}<div class="protection-lights"><b>MOTOR PROTECTION</b>${['OVERCURRENT','PHASE LOSS','PHASE SEQ','STALL','OVERLOAD'].map(l=>`<span><i class="led"></i>${l}</span>`).join('')}</div><div class="status-lights"><b>STARTER STATUS</b><div class="ledrow"><span class="led" id="fault-led"></span><span id="fault-label">FAULT</span></div><div class="ledrow"><span class="led" id="run-led"></span> RUN</div><div class="ledrow"><span class="led on" id="ready-led"></span> READY</div></div><div class="serial-cover" aria-hidden="true"><i></i></div><span class="serial-caption">SERIAL PORT<br>RS-232</span>${terminals(['13','14/23','24'],true)}</div></div><div class="housing-cap bottom-cap">${terminals(['U / 2T1','V / 4T2','W / 6T3'])}</div></div><div class="hardware-status"><span class="dot"></span><span id="state-label">PRONTO</span><small>Representação didática · sem marca</small></div><button class="btn" id="simulate" ${currentMode?'hidden':''}>${stop?'Simular parada':'Simular partida'} <span>▷</span></button><p class="hardware-hint">${currentMode?'Ajuste MOTOR CURRENT pelo trimpot.':'Ajuste pelos trimpots.<br>Tempo visual do ensaio acelerado.'}</p></div>`;
}
function simulationPanel(s,stop){const p=run().params;return `<div class="sim-layout">${frontPanel(s,stop)}<div class="scope"><div class="scope-head"><span>MONITOR DO ENSAIO</span><span id="elapsed">t = 0,0 s</span></div><svg id="chart" viewBox="0 0 480 255" role="img" aria-label="Gráfico simulado de tensão, corrente e velocidade"></svg><div class="legend"><span style="--color:#367e5a">Tensão (% Un)</span><span style="--color:#cc873e">Corrente (× In motor)</span><span style="--color:#577fa4">Velocidade (% nominal)</span></div><div class="meters"><div class="meter"><small>TENSÃO EFICAZ</small><strong id="volts">0 V</strong></div><div class="meter"><small>CORRENTE</small><strong id="amps">0 A</strong></div><div class="meter"><small>ROTAÇÃO APROX.</small><strong id="rpm">0 rpm</strong></div></div><div class="shaft-meter"><svg viewBox="0 0 56 56" width="40" height="40" role="img" aria-label="Eixo do motor simulado"><circle cx="28" cy="28" r="24" fill="#dce7d5" stroke="#78916e"/><g id="shaft"><path d="M28 28L28 6M28 28L47 39M28 28L9 39" stroke="#527958" stroke-width="6"/><circle cx="28" cy="28" r="5" fill="#254d3a"/></g></svg><span>Movimento do eixo<br><small>Animação ilustrativa</small></span></div><div class="sim-status" id="sim-status" role="status" aria-live="polite">${stop?'Compare OFF e uma rampa de parada.':'Ajuste os trimpots e inicie o ensaio.'}</div><div id="sim-details" class="small"></div></div></div><button class="mini-link" data-action="model">Como este modelo calcula as curvas? ↗</button><div class="small" style="margin-top:9px">Curvas aproximadas, calculadas por modelo didático. Não são medições, curvas de fabricante ou validação de engenharia.</div>`;}
function drawChart(samples,extent){const svg=$('#chart');if(!svg)return;const xmax=Math.max(4,extent),imax=Math.max(6,Math.ceil(Math.max(0,...samples.map(d=>d.current/active.amps)))),pts=(key,scale)=>samples.map(d=>`${42+d.t/xmax*390},${218-d[key]*scale*180}`).join(' ');svg.innerHTML=`<rect x="42" y="38" width="390" height="180" fill="#fff"/>${[0,.25,.5,.75,1].map(v=>`<path d="M42 ${218-v*180}H432" stroke="#dce4d7" stroke-dasharray="3 4"/><text x="34" y="${222-v*180}" text-anchor="end" font-size="10" fill="#768471">${Math.round(v*100)}</text><text x="440" y="${222-v*180}" font-size="10" fill="#b48048">${fmt(v*imax,1)}</text>`).join('')}<text x="18" y="21" font-size="9" fill="#758370">% Un / % n</text><text x="412" y="21" font-size="9" fill="#a8783e">I / In</text>${[0,.25,.5,.75,1].map(v=>`<text x="${42+v*390}" y="238" text-anchor="middle" font-size="10" fill="#768471">${fmt(v*xmax,1)}</text>`).join('')}<text x="237" y="253" text-anchor="middle" font-size="9" fill="#768471">tempo (s)</text><polyline points="${pts('u',1)}" fill="none" stroke="#367e5a" stroke-width="2.5"/><polyline points="${samples.map(d=>`${42+d.t/xmax*390},${218-d.current/active.amps/imax*180}`).join(' ')}" fill="none" stroke="#cc873e" stroke-width="2.5"/><polyline points="${pts('w',1)}" fill="none" stroke="#577fa4" stroke-width="2.5"/>`;if(active.steps[index].type==='simulation'&&samples.length&&run().params.ramp<=xmax){const x=42+run().params.ramp/xmax*390;svg.innerHTML+=`<path d="M${x} 38V218" stroke="#8b79b2" stroke-dasharray="5 4"/><text x="${Math.min(x,350)}" y="32" font-size="9" fill="#736391">Fim da rampa</text>`;}}
function stopAnimation(){if(animation){cancelAnimationFrame(animation);animation=null;}}
function bindSimulation(stop){drawChart([],run().params.ramp+4);$$('[data-param]').forEach(el=>el.oninput=()=>{stopAnimation();$('#simulate').disabled=false;const key=el.dataset.param,value=Number(el.value);run().params[key]=value;save();$(`#${key}-value`).textContent=key==='decel'&&value===0?'OFF':value+' '+el.dataset.unit;$(`#${key}-knob`).style.setProperty('--angle',((value-Number(el.min))/(Number(el.max)-Number(el.min))*270-135)+'deg');lastResult=null;$('#sim-details').innerHTML='';$('#fault-led').className='led';$('#run-led').className='led';$('#fault-label').textContent='FAULT';$('#state-label').textContent='AJUSTE ALTERADO';drawChart([],run().params.ramp+4);$('#sim-status').textContent='Ajuste alterado. Execute um novo ensaio para validar.';$('#submit').disabled=false;});$('#simulate').onclick=()=>performSimulation(stop);}
function resultText(r){
 if(r.fault==='startingDuty')return `Capacidade de partida excedida no exercício: corrente igual ou superior a 3 × In da soft-starter (${fmt(3*active.ssw,1)} A) mantida por ${fmt(r.maxDutyDuration,2)} s. Como motor e soft-starter têm a mesma corrente nominal, o ensaio foi interrompido antes do fim da rampa. Reveja torque inicial, carga, tempo e dimensionamento; não aumente a rampa automaticamente. Este é um alerta didático de capacidade, não a reprodução do instante de disparo térmico real da WEG.`;
 if(r.fault==='beforeBypass')return 'Sobrecorrente antes do by-pass: a corrente no fim da rampa atingiu o limiar da soft-starter. Investigue carga, torque inicial e aceleração incompleta.';
 if(r.fault==='stall')return 'Stall na transição: corrente igual ou superior a 2 × a referência ajustada do motor. Verifique carga, travamento, pedestal e tempo de aceleração antes de resetar.';
 if(r.fault==='overcurrent')return 'Sobrecorrente em regime: corrente superior a 3 × a referência ajustada do motor por mais de 1 s. Esse critério se aplica após a rampa, e não ao pico inicial.';
 if(r.fault==='bypassOvercurrent')return 'Sobrecorrente no by-pass por mais de 1 s. Investigue corrente da carga e dimensionamento antes de novo ensaio.';
 if(!r.moved)return 'O torque inicial foi insuficiente para vencer a carga. Reveja o pedestal: aumentar apenas o tempo pode prolongar a espera e o aquecimento.';
 if(r.impact)return 'A aceleração calculada foi brusca para esta carga. Compare pedestal e tempo de rampa, preservando torque suficiente para iniciar o movimento.';
 if(r.thermalCaution)return 'Corrente mantida por tempo excessivo no modelo: há indicação didática de solicitação térmica elevada. Reveja carga, ajustes, seleção e intervalo entre partidas. Não é uma reprodução da proteção térmica real.';
 if(r.incomplete)return `Ao final da rampa, o motor estava em ${fmt(r.endRampSpeed,1)}% da rotação nominal e ainda apresentava aceleração significativa no modelo. O fim da rampa de tensão não garante o fim da aceleração. Reveja tempo, pedestal e carga em conjunto; aumentar o tempo não resolve todos os casos.`;
 return 'Partida coerente com o modelo: torque inicial suficiente, aceleração suave e aproximação do regime ao término da rampa, sem falha simulada. Confira também pico, duração da corrente e ciclo permitido.';
}
function peakAdvice(r){return r.peakBand==='low'?'Pico até 2 × In: corrente relativamente baixa; confirme que há torque e aceleração suficientes.':r.peakBand==='moderate'?'Pico entre 2 e 3 × In: referência inicial favorável, se a duração e a carga forem compatíveis.':r.peakBand==='elevated'?'Pico entre 3 e 4 × In: pode ser aceitável; avalie duração, dimensionamento e transição.':'Pico acima de 4 × In: exige maior atenção à capacidade elétrica e térmica do conjunto. Não é, sozinho, um limiar universal de falha.';}

function performSimulation(stop){stopAnimation();const s=active,p=run().params,res=stop?simulateStop(s,p):simulateMotor(s,p);lastResult=null;$('#simulate').disabled=true;$('#submit').disabled=true;$$('[data-param]').forEach(e=>e.disabled=true);$('#ready-led').className='led on blink';$('#run-led').className='led';$('#fault-led').className='led';$('#fault-label').textContent='FAULT';$('#state-label').textContent=stop?'PARANDO':'PARTINDO';$('#sim-status').textContent=stop?'Simulando retirada da tensão…':'Simulando aceleração da carga…';$('#sim-details').textContent='';const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,t0=performance.now(),length=reduced?1:3200;
function frame(now){const ratio=Math.min(1,(now-t0)/length),n=Math.max(1,Math.round(res.samples.length*ratio)),d=res.samples[n-1];drawChart(res.samples.slice(0,n),res.samples.at(-1).t);$('#volts').textContent=fmt(d.u*s.voltage)+' V';$('#amps').textContent=fmt(d.current,1)+' A';$('#rpm').textContent=fmt(d.w*s.rpm)+' rpm';$('#elapsed').textContent='t = '+fmt(d.t,1)+' s';$('#shaft').setAttribute('transform',`rotate(${d.t*d.w*180} 28 28)`);if(ratio<1){animation=requestAnimationFrame(frame);return;}animation=null;lastResult=res;$('#simulate').disabled=false;$('#submit').disabled=false;$$('[data-param]').forEach(e=>e.disabled=false);$('#ready-led').className='led on';$('#state-label').textContent=stop?'PARADO':res.fault==='startingDuty'?'LIMITE DE PARTIDA · SIMULAÇÃO':res.fault?'FALHA':!res.good?'TENSÃO PLENA · REVER AJUSTES':'TENSÃO PLENA';$('#run-led').className='led'+(!stop&&!res.fault?' on':'');$('#fault-led').className='led'+(res.fault?(res.fault==='startingDuty'?' red':' red blink'):'');$('#fault-label').textContent=res.fault==='startingDuty'?'CAPACIDADE · SIMULAÇÃO':res.fault==='stall'?'STALL':res.fault==='beforeBypass'?'INTERNAL FAULT · 4 PISCADAS':res.fault==='overcurrent'?'OVERCURRENT':res.fault==='bypassOvercurrent'?'INTERNAL FAULT · 5 PISCADAS':'FAULT';$('#sim-status').textContent=stop?(p.decel===0?'Parada livre: torque elétrico removido imediatamente.':'Tensão reduzida progressivamente. A velocidade responde à carga; não há frenagem garantida.') :resultText(res);if(!stop){$('#sim-details').innerHTML=`${res.rampReached?`Velocidade ao fim da rampa (${fmt(p.ramp,0)} s): <b>${fmt(res.endRampSpeed,1)}% da nominal (${fmt(res.atRamp.w*s.rpm)} rpm)</b>`:`Rampa interrompida em <b>${fmt(res.interruptedAt,2)} s</b>; o tempo configurado de ${fmt(p.ramp)} s não foi concluído.<br>Velocidade na interrupção: <b>${fmt(res.samples.at(-1).w*100,1)}% da nominal</b>`}<br>Primeiro movimento: <b>${res.firstMove===null?'não ocorreu':fmt(res.firstMove,1)+' s'}</b><br>Pico de corrente: <b>${fmt(res.peakCurrent,1)} A (${fmt(res.peakCurrent/s.amps,2)} × In)</b><br>${res.rampReached?`Corrente no fim da rampa: <b>${fmt(res.atRamp.current,1)} A (${fmt(res.atRamp.current/s.amps,2)} × In motor)</b>`:`Corrente na interrupção: <b>${fmt(res.samples.at(-1).current,1)} A</b>`}<br>Tempo com corrente acima de 2 × In motor: <b>${fmt(res.highCurrentDuration,1)} s</b>${s.startingDutyLesson?`<br>Maior intervalo contínuo com corrente ≥ ${fmt(3*s.ssw,1)} A (3 × In soft-starter): <b>${fmt(res.maxDutyDuration,2)} s</b> · referência do exercício: 10 s`:''}<p>${peakAdvice(res)}</p><p>As faixas de pico são referências didáticas, não limites universais de proteção. In motor = ${fmt(s.amps,1)} A; In soft-starter = ${s.ssw} A.</p>`;run().tests.push({at:new Date().toISOString(),params:{...p},fault:res.fault,good:res.good,energy:res.energy});run().tests=run().tests.slice(-30);save();}}
animation=requestAnimationFrame(frame);}
function modal(title,body){const d=$('#modal');d.className='modal';d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="btn light" id="close-modal" aria-label="Fechar janela">×</button></div><div class="modal-body">${body}</div>`;$('#close-modal').onclick=()=>d.close();d.showModal();d.onclick=e=>{if(e.target===d)d.close();};}
function components(){return `<p>Combinações de proteção para os equipamentos desta atividade. Não são uma especificação universal de coordenação.</p><div class="table-wrap"><table class="data"><tr><th>SSW</th><th>K1</th><th>Potência F1–F3</th><th>Controle</th></tr>${[[3,'CWM09','D 10 A'],[10,'CWM12','D 16 A'],[16,'CWM18','D 25 A'],[23,'CWM25','D 35 A'],[30,'CWM32','D 50 A'],[45,'CWM50','D 63 A'],[60,'CWM65','NH 100 A'],[85,'CWM95','NH 125 A']].map(v=>`<tr><td>${v[0]} A</td><td>${v[1]}</td><td>Tipo ${v[2]}</td><td>Tipo D 6 A</td></tr>`).join('')}</table></div><p class="small">Verificar capacidade de curto-circuito, tensão, coordenação, condutores, esquema e requisitos locais. As combinações devem ser avaliadas de acordo com o esquema e as condições da instalação.</p>`;}
function terminals(){return `<table class="data"><tr><th>Bornes</th><th>Função padrão</th></tr><tr><td>R/1L1, S/3L2, T/5L3</td><td>Entrada trifásica de potência. Versões 220–460 V e 460–575 V.</td></tr><tr><td>U/2T1, V/4T2, W/6T3</td><td>Saída para motor trifásico. PE na carcaça; não confundir com neutro do motor.</td></tr><tr><td>A1 / A2</td><td>Eletrônica: 90–250 Vca, 50/60 Hz.</td></tr><tr><td>DI1 / DI2</td><td>Entradas 90–250 Vca. Padrão: aciona/desaciona e reset, respectivamente; funções dependem da programação.</td></tr><tr><td>13 – 14/23</td><td>Operação: fecha ao acionar e permanece durante a desaceleração configurada por trimpot.</td></tr><tr><td>14/23 – 24</td><td>Tensão plena: fecha com tensão plena e abre ao desacionar; função pode ser alterada via P277.</td></tr></table><p class="small">Saídas a relé: 1 A / 250 Vca.  Bornes ilustrados para identificação, sem editor de fiação.</p>`;}
function modelInfo(){return `<p>Modelo simplificado de ensino, com passo de 0,05 s. Tensão, corrente e velocidade são curvas calculadas; não são medições nem uma reprodução do firmware do equipamento.</p><p>A rampa eleva a tensão do pedestal até 100%. O torque aproximado depende de u² e da velocidade; a aceleração depende da diferença entre torque do motor e torque da carga, dividida pela inércia. Bomba e ventilador usam carga quadrática; a esteira inclui atrito inicial e carga aproximadamente constante.</p><p>A corrente diminui conforme a velocidade se aproxima do regime. O gráfico continua por alguns segundos após a rampa para mostrar uma possível aceleração residual. A porcentagem apresentada é medida exatamente no término da rampa, em relação à rotação nominal da placa.</p><p>A avaliação conjunta considera torque inicial, aceleração brusca e proximidade do equilíbrio mecânico ao fim da rampa. A tolerância interna de equilíbrio de torque é numérica e própria deste modelo; não representa um percentual de velocidade exigido pelo fabricante. Nenhum percentual universal de 90%, 95% ou 98% é imposto ao aluno.</p><p>Os patamares de pico até 2, de 2 a 3, de 3 a 4 e acima de 4 × In motor são referências didáticas, sem reprovação automática por pico. Capacidade de partida: referência de 3 × In da soft-starter por 10 s nas condições especificadas, distinta dos limiares das proteções. Não é um limite universal de duração da rampa.</p><p>Na transição, o modelo verifica Stall (≥ 2 × a corrente ajustada do motor) e sobrecorrente antes do by-pass (≥ 37,5 A para as versões usadas). Em regime, verifica corrente superior a 3 × a referência ajustada por mais de 1 s e sobrecorrente no by-pass. A situação 3 usa correntes nominais iguais e interrompe o ensaio quando a corrente permanece igual ou superior a 3 × In da soft-starter por mais de 10 s contínuos. Esse alerta demonstra o limite de capacidade adotado no exercício e não reproduz a curva térmica real. Um pico isolado ou uma rampa acima de 10 s não dispara esse alerta. A prioridade de apresentação de falhas simultâneas é didática.</p><p>Uma estimativa térmica interna orienta alertas de corrente prolongada. Não reproduz curvas de disparo, temperatura, memória térmica ou autorização para repetir partidas. Respeite a capacidade de serviço e o intervalo de partidas do equipamento.</p><p>A parada reduz a tensão e integra a resposta mecânica. Pressão, vazão e golpe de aríete não são calculados: a rampa não garante frenagem nem elimina transientes hidráulicos.</p>`;}

function library(){modal('Biblioteca técnica',`<p>Consulte durante a missão. As referências ajudam a decidir; não é necessário decorar valores.</p><details open><summary>SSW-05 Plus · ajustes e limites</summary><table class="data"><tr><th>Ajuste / capacidade</th><th>Faixa do manual</th></tr>${[['INITIAL VOLTAGE','30–80% Un'],['ACCEL TIME','1–20 s'],['DECEL TIME','OFF até 20 s'],['MOTOR CURRENT','30–100% da corrente nominal da SSW'],['Ciclo geral especificado','3 × In SSW durante 10 s'],['Partidas','4/h, uma a cada 15 min'],['Condições','0–55 °C; até 1.000 m sem redução por altitude']].map(v=>`<tr><td>${v[0]}</td><td>${v[1]}</td></tr>`).join('')}</table><p class="small">Características do equipamento. Não extrapolar a capacidade de serviço a partir de um ensaio simplificado.</p></details><details><summary>Proteções · como distinguir as indicações</summary>${FAULTS.map(f=>`<h4 style="margin-top:24px">${f.name}</h4><p><b>${f.led}${f.flashes?' · '+f.flashes+' piscadas':''}${f.code?' · '+f.code:''}</b><br>${f.condition}</p><p>${f.action}</p>`).join('')}</details><details><summary>Componentes e proteção externa</summary>${components()}</details><details><summary>Bornes e funções</summary>${terminals()}</details><details><summary>GED-13 · recorte da aula</summary><p>Referência didática da Tabela 12 presente no Notion. A revisão do recorte não está identificada. Este simulador não certifica atendimento à edição vigente.</p><img src="ged13.png" alt="Tabela 12 do material: limites de partida direta e métodos de redução da corrente"><p>Em 220/127 V, a tensão entre fases é 220 V. Em 380/220 V, é 380 V. A tabela não implica que toda aplicação fora da faixa direta exija exclusivamente soft-starter.</p><a href="${SOURCES.cpfl}" target="_blank" rel="noopener">Consultar normas na CPFL ↗</a></details><details><summary>Modelo de simulação e suas hipóteses</summary>${modelInfo()}</details><details><summary>Fontes utilizadas</summary><p>${SOURCES.manual}. Páginas impressas da seção em português: 65–76; §§3–17.</p><p><a href="${SOURCES.notion}" target="_blank" rel="noopener">Material de aula — Módulo 2: Soft-Starter ↗</a></p><p>Dados dos motores e condições operacionais: hipóteses didáticas, identificadas nas placas. Modelos, faixas de ajuste, bornes e limiares indicados: manual fornecido. Recorte GED: imagem disponibilizada no material de aula.</p></details>`);}
function guide(){modal('Seu laboratório de decisões',`<div class="eyebrow">SITUAÇÃO → ANÁLISE → DECISÃO → CONSEQUÊNCIA</div><p>Você assume uma ordem de serviço e libera cada etapa com uma decisão fundamentada. Se errar, leia a explicação e tente novamente.</p><ol><li><b>Leia a solicitação.</b> Nem toda aplicação precisa de soft-starter.</li><li><b>Consulte as evidências.</b> Abra a placa, a tabela e a biblioteca durante a análise.</li><li><b>Experimente no painel.</b> Os ajustes alteram as curvas. Executar um ensaio não conta como resposta errada; clicar em validar registra a decisão.</li><li><b>Conclua o parecer.</b> O resultado na tela mostra primeiras tentativas e pontos de revisão.</li></ol><h3>Para usar em aula</h3><p>Projete uma missão e peça aos grupos que justifiquem cada decisão. Use o modo projeção para ampliar o conteúdo. As durações são estimativas e podem variar conforme a discussão.</p><p><b>Aprendizagem sem penalizar a exploração:</b> o indicador de primeiras tentativas considera decisões confirmadas. A lista de comissionamento é uma revisão e não entra no percentual.</p><p><b>Atividade:</b> mantida apenas durante a situação atual. Ao voltar à tela inicial, todas as situações começam novamente do zero. O resultado é exibido na tela, sem salvamento.</p><p><a class="btn light" href="softstarter-lab.zip" download>Baixar código-fonte e instruções ↓</a></p><p><b>Documentação:</b> a GED exibida é o recorte da aula; a revisão não foi identificada. Os gráficos são aproximações educacionais. Esta atividade não habilita intervenção elétrica real.</p>`);}
function metrics(s){const r=run(s),decision=s.steps.filter(st=>st.type!=='checklist'),answered=decision.filter(st=>r.answers[st.id]?.passed),first=decision.filter(st=>r.answers[st.id]?.passed&&r.answers[st.id].attempts===1).length,errors=decision.reduce((n,st)=>n+(r.answers[st.id]?.errors||0),0);return {r,decision,answered,first,errors,pct:Math.round(first/decision.length*100)};}
function report(s){stopAnimation();active=s;route='report';const {r,decision,first,errors,pct}=metrics(s);shell(`<div class="report-hero"><div class="eyebrow">✓ MISSÃO ${s.num} CONCLUÍDA</div><h1>${s.name}</h1><p style="margin-bottom:0">${s.conclusion}</p></div><div class="report-grid"><div class="stat"><strong>${pct}%</strong><span>Decisões certas na primeira tentativa</span></div><div class="stat"><strong>${decision.length}</strong><span>Decisões técnicas concluídas</span></div><div class="stat"><strong>${errors}</strong><span>Tentativas a revisar</span></div></div><div class="panel" style="margin-top:22px"><h3>Seu resultado nesta situação</h3><div class="table-wrap"><table class="data"><tr><th>Etapa</th><th>Tentativas</th><th>Resultado</th></tr>${decision.map(st=>`<tr><td>${st.title}</td><td>${r.answers[st.id]?.attempts||0}</td><td>${r.answers[st.id]?.errors?'Concluída após revisão':'Correta na primeira tentativa'}</td></tr>`).join('')}</table></div><p class="small" style="margin-top:18px">${first} de ${decision.length} decisões corretas na primeira tentativa. Ensaios exploratórios e confirmações da lista final não entram nesse cálculo.</p>${s.ssw?`<h3 style="margin-top:25px">Parâmetros finais do painel</h3><div class="facts">${[['MOTOR CURRENT',r.params.current+'%'],['INITIAL VOLTAGE',r.params.initial+'%'],['ACCEL TIME',r.params.ramp+' s'],['DECEL TIME',r.params.decel?r.params.decel+' s':'OFF']].map(([a,b])=>`<div class="fact"><small>${a}</small><strong>${b}</strong></div>`).join('')}</div><p class="small">${r.tests.length} ensaios registrados (até os últimos 30). Ajustes válidos para esta hipótese didática, não prescrições universais.</p>`:''}<h3 style="margin-top:25px">Conceitos trabalhados</h3><p class="small">${s.kind==='conveyor'?'Partida suave em velocidade fixa, atrito inicial, torque resistente, pedestal, estabilidade das caixas, rampas, diagnóstico Stall e parada livre.':'Leitura de placa, seleção por corrente e tensão, proteção externa, bornes, corrente do motor, torque inicial, rampa de tensão, diagnóstico e limites do ciclo.'}</p><p class="small">Concluído em ${r.finished?new Date(r.finished).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):''} · Prof. Douglas Ferreira da Silva.</p><p class="print-only">Simulador Industrial — Soft-Starter. Resultado educacional; não é laudo técnico de uma instalação.</p></div><div class="toolrow no-print"><button class="btn light" data-action="home">Voltar às missões</button><button class="btn light" data-action="restart">Reiniciar missão</button></div>`);window.scrollTo(0,0);}
function reports(){stopAnimation();route='reports';shell(`<div class="pagehead"><div><h2>Resultados</h2><p class="sub">O registro das decisões que você construiu.</p></div></div><div class="cards">${SCENARIOS.map(s=>{const r=run(s);return `<article class="scenario"><div class="card-art ${s.kind}">${motorArt(s.kind)}</div><div class="card-body"><h3>${s.name}</h3><p>${r.done?'Missão concluída · '+metrics(s).pct+'% na primeira tentativa':'Conclua o percurso para gerar o relatório.'}</p><button class="btn ${r.done?'':'light'}" data-start="${s.id}">${r.done?'Abrir relatório':'Continuar atividade'} →</button></div></article>`}).join('')}</div>`);}
function bindGlobal(){$$('[data-start]').forEach(e=>e.onclick=()=>start(e.dataset.start));$$('[data-action]').forEach(e=>e.onclick=ev=>{ev.preventDefault();switch(e.dataset.action){case'home':home();break;case'reference':library();break;case'guide':guide();break;case'reports':reports();break;case'projection':db.projection=!db.projection;save();document.body.classList.toggle('projection',db.projection);e.textContent=db.projection?'Sair da projeção':'Modo projeção';e.setAttribute('aria-pressed',String(db.projection));break;case'ged':modal('Tabela 12 · recorte do material de aula',`<p>Revisão não identificada no recorte. Consulte a tabela para esta atividade; um projeto real exige verificação da edição vigente.</p><a href="ged13.png" target="_blank">Abrir imagem em tamanho integral ↗</a><img src="ged13.png" alt="Tabela 12: dispositivos para redução da corrente de partida de motores trifásicos"><p class="small">Fonte: material do professor no Notion. Não interpretar redução de corrente como obrigatoriedade exclusiva de soft-starter.</p>`);break;case'components':modal('Combinações de proteção',components());break;case'terminals':modal('Bornes da SSW-05 Plus',terminals());break;case'model':modal('O que está por trás das curvas',modelInfo());break;case'restart':modal('Reiniciar esta missão?',`<p>O progresso e as tentativas de <b>${active.name}</b> serão apagados neste navegador. As outras missões serão mantidas.</p><div class="toolrow"><button class="btn" id="confirm-restart">Reiniciar missão</button><button class="btn light" id="cancel-restart">Manter progresso</button></div>`);$('#confirm-restart').onclick=()=>{const id=active.id;delete db.runs[id];save();$('#modal').close();start(id);};$('#cancel-restart').onclick=()=>$('#modal').close();break;}});}
// Página contínua: cada decisão revela o próximo trecho da situação.
const legacyRenderStep=renderStep,legacySubmit=submit,legacyNext=next;
let flowHistory={},flowTimer=null;
shell=function(inner){document.body.classList.remove('projection');$('#app').innerHTML=`<div class="webpage"><header class="site-signature"><span class="site-symbol">ϟ</span><span>Soft-Starter <b>Lab</b></span><small>UMA EXPERIÊNCIA DE APRENDIZAGEM</small></header><main class="content">${inner}</main><footer class="site-footer">Acionamentos eletrônicos de máquinas elétricas <span>Prof. Douglas Ferreira da Silva</span></footer></div>`;bindGlobal();};
home=function(){clearTimeout(flowTimer);stopAnimation();db.runs={};flowHistory={};active=null;index=0;route='home';shell(`<section class="welcome"><div class="eyebrow">APRENDA NA PRÁTICA · SOFT-STARTER</div><h1>Uma situação real.<br><span>Uma decisão de cada vez.</span></h1><p>Você é o técnico responsável. Escolha uma situação, conheça o problema e descubra o que acontece quando suas decisões entram em ação.</p></section><section class="cards welcome-cards">${SCENARIOS.map(s=>`<article class="scenario"><button class="visual-card ${s.kind}" data-start="${s.id}" aria-label="Selecionar ${s.name}"><span class="card-number">SITUAÇÃO ${s.num}</span>${motorArt(s.kind)}<span class="visual-arrow">↗</span></button><div class="card-body"><div class="eyebrow">${s.tag} <span>· ${s.duration}</span></div><h3>${s.name}</h3><p>${s.short}</p><button class="btn" data-start="${s.id}">${run(s).done?'Rever resultado':Object.keys(run(s).answers).length?'Continuar situação':'Explorar situação'} <span>→</span></button></div></article>`).join('')}</section><p class="welcome-note">Observe. Experimente. Entenda.<br><span>Sem pressa: observe os resultados e aprenda a cada tentativa.</span></p>`);window.scrollTo(0,0);};
function historyCard(i){const s=active,st=s.steps[i],a=run().answers[st.id];if(!a?.passed)return '';if(flowHistory[s.id]?.[st.id])return flowHistory[s.id][st.id];return `<article class="flow-past"><div class="eyebrow">ETAPA ${String(i+1).padStart(2,'0')} · CONCLUÍDA ✓</div><h2>${st.title}</h2><p>${st.context}</p>${st.show==='plate'?plate(s):''}<div class="result-banner">${st.type==='choice'?st.why[st.correct]:'Análise concluída e validada nesta situação.'}</div></article>`;}
renderStep=function(){const oldMain=$('main.content');const oldFlow=oldMain?.querySelector('.story-flow');const previous=oldMain?.querySelector('.flow-current');const scrollYBefore=window.scrollY;legacyRenderStep();const current=$('.workspace>.panel');current.classList.add('flow-current');current.id='current-stage';if(index===0){current.querySelector('.os')?.remove();current.querySelector('.facts')?.remove();}const stage=current.outerHTML;const past=active.steps.slice(0,index).map((_,i)=>historyCard(i)).join('');const intro=`<section class="story-intro"><div class="story-copy"><button class="mini-link" data-action="home">← Escolher outra situação</button><div class="eyebrow">SITUAÇÃO ${active.num} · ${active.tag}</div><h1>${active.name}</h1><p>${active.brief}</p>${facts(active)}</div><div class="story-art ${active.kind}">${motorArt(active.kind,true)}</div></section><div class="story-instruction"><span>↓</span> Leia o contexto e tome sua primeira decisão.<br>O próximo passo aparece conforme você avança.</div>`;
// Move the live panel instead of recreating it, preserving all its event handlers.
const main=$('main.content');const live=current;if(oldFlow&&previous&&index>0){previous.classList.replace('flow-current','flow-past');previous.removeAttribute('id');previous.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));previous.querySelectorAll('[data-param],[data-option],[data-action]').forEach(e=>{e.removeAttribute('data-param');e.removeAttribute('data-option');e.removeAttribute('data-action');});previous.querySelectorAll('button,input').forEach(e=>e.disabled=true);previous.querySelector('.step-actions')?.remove();oldFlow.append(live);main.replaceWith(oldMain);window.scrollTo(0,scrollYBefore);}else{main.innerHTML=intro+`<div class="story-flow">${past}<div id="live-slot"></div></div>`;$('#live-slot').replaceWith(live);}bindGlobal();$('#next').style.display='none';if(run().answers[active.steps[index].id]?.passed){$('#next').style.display='inline-flex';}const label=$('.flow-current>.eyebrow');if(label)label.innerHTML=`PASSO ${String(index+1).padStart(2,'0')} <span class="step-dot"></span> ${active.steps[index].type==='simulation'?'HORA DE EXPERIMENTAR':'SUA DECISÃO'}`;};
submit=function(){legacySubmit();const st=active.steps[index];if(!run().answers[st.id]?.passed)return;const clone=$('.flow-current').cloneNode(true);clone.classList.remove('flow-current');clone.classList.add('flow-past');clone.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));clone.removeAttribute('id');clone.querySelectorAll('button,input').forEach(e=>e.disabled=true);clone.querySelectorAll('[data-param],[data-option],[data-action]').forEach(e=>{e.removeAttribute('data-param');e.removeAttribute('data-option');e.removeAttribute('data-action');});clone.querySelector('.step-actions')?.remove();flowHistory[active.id]??={};flowHistory[active.id][st.id]=clone.outerHTML;clearTimeout(flowTimer);flowTimer=setTimeout(()=>{next();},650);};
next=function(){legacyNext();if(route==='mission')requestAnimationFrame(()=>$('#current-stage')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));};
// Prevent pending automatic progression when leaving a situation.
const baseStart=start;start=function(id){clearTimeout(flowTimer);baseStart(id);};
home();
